//! Pokémon Crystal RAM and ROM addresses, generated by `tools/gen_syms.py`
//! from the pret/pokecrystal symbol files (`symbols` branch). Don't edit by
//! hand. Each address is the same in Crystal 1.0 and 1.1.

use crate::mem::Sym;

/// Shadow OAM: the sprites the game queued for the next frame.
pub const W_SHADOW_OAM: Sym = Sym::new(0x00, 0xC400);
/// 20x18 tile IDs of the screen as the game composed it.
pub const W_TILEMAP: Sym = Sym::new(0x00, 0xC4A0);
/// 20x18 CGB attributes matching wTilemap.
pub const W_ATTRMAP: Sym = Sym::new(0x00, 0xCDD9);
/// The current map's blocks with a 3-block border holding connection strips (1300 bytes).
pub const W_OVERWORLD_MAP_BLOCKS: Sym = Sym::new(0x00, 0xC800);
/// Pixels the camera moved this step that objects haven't absorbed yet.
pub const W_PLAYER_BG_MAP_OFFSET_X: Sym = Sym::new(0x01, 0xD14C);
pub const W_PLAYER_BG_MAP_OFFSET_Y: Sym = Sym::new(0x01, 0xD14D);
pub const W_PLAYER_STEP_FLAGS: Sym = Sym::new(0x01, 0xD150);
/// VRAM BG map address of the screen's top-left tile.
pub const W_BG_MAP_ANCHOR: Sym = Sym::new(0x01, 0xD152);
/// Address in wOverworldMapBlocks of the block at the screen's top-left (minus the half-block).
pub const W_OVERWORLD_MAP_ANCHOR: Sym = Sym::new(0x01, 0xD194);
/// 0 or 1: which half of the anchor block the screen starts on.
pub const W_PLAYER_METATILE_Y: Sym = Sym::new(0x01, 0xD196);
pub const W_PLAYER_METATILE_X: Sym = Sym::new(0x01, 0xD197);
pub const W_MAP_TILESET: Sym = Sym::new(0x01, 0xD199);
/// Drawn where wOverworldMapBlocks holds 0.
pub const W_MAP_BORDER_BLOCK: Sym = Sym::new(0x01, 0xD19D);
/// In blocks (32x32 px).
pub const W_MAP_HEIGHT: Sym = Sym::new(0x01, 0xD19E);
/// In blocks (32x32 px).
pub const W_MAP_WIDTH: Sym = Sym::new(0x01, 0xD19F);
/// ROM bank of the tileset's metatiles (16 tile IDs per block).
pub const W_TILESET_BLOCKS_BANK: Sym = Sym::new(0x01, 0xD1DC);
pub const W_TILESET_BLOCKS_ADDRESS: Sym = Sym::new(0x01, 0xD1DD);
/// Pointer, in the bank of _LoadOverworldAttrmapPals, to the tileset's palette map (a nibble per tile ID).
pub const W_TILESET_PALETTES: Sym = Sym::new(0x01, 0xD1E6);
/// Nonzero in battle.
pub const W_BATTLE_MODE: Sym = Sym::new(0x01, 0xD22D);
/// 13 object structs; the player is the first.
pub const W_OBJECT_STRUCTS: Sym = Sym::new(0x01, 0xD4D6);
pub const W_MAP_OBJECTS: Sym = Sym::new(0x01, 0xD71E);
pub const W_TIME_OF_DAY_PAL: Sym = Sym::new(0x01, 0xD841);
/// 1 while the main loop waits for VBlank in DelayFrame; the VBlank handler clears it.
pub const W_V_BLANK_OCCURRED: Sym = Sym::new(0x00, 0xCFB3);
pub const W_MAP_GROUP: Sym = Sym::new(0x01, 0xDCB5);
pub const W_MAP_NUMBER: Sym = Sym::new(0x01, 0xDCB6);
/// Player position in 16 px steps.
pub const W_Y_COORD: Sym = Sym::new(0x01, 0xDCB7);
pub const W_X_COORD: Sym = Sym::new(0x01, 0xDCB8);
pub const W_PARTY_COUNT: Sym = Sym::new(0x01, 0xDCD7);
pub const W_PARTY_SPECIES: Sym = Sym::new(0x01, 0xDCD8);
pub const W_WINDOW_STACK_POINTER: Sym = Sym::new(0x00, 0xCF71);
/// The scroll the VBlank handler copies to rSCX for the next frame.
pub const H_SCX: Sym = Sym::new(0x00, 0xFFCF);
pub const H_SCY: Sym = Sym::new(0x00, 0xFFD0);
pub const H_WY: Sym = Sym::new(0x00, 0xFFD2);
pub const H_ROM_BANK: Sym = Sym::new(0x00, 0xFF9D);
/// ROM: pointer table, per FACING_* value, to OAM templates (count, then y, x, attributes, tile).
pub const FACINGS: Sym = Sym::new(0x01, 0x4049);
/// ROM: only its bank is used (the palette maps live in that bank).
pub const LOAD_OVERWORLD_ATTRMAP_PALS: Sym = Sym::new(0x13, 0x4000);
